-- 东微电子 纳入研究池 (2026-10-16)

INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'东微电子',null,'semiconductor','material',false,'C 轮',null,30,null,'2026-04','{"name":"东微电子","industry":"semiconductor","seg":"material","listed":false,"desc":"河南东微电子材料有限公司（2018-04-13 成立，总部河南郑州航空港经济综合实验区），董事长王永超、CEO 赵泽良，核心团队为海归博士、平均 10 年以上行业经验，曾任职英特尔、阿斯麦（ASML）、贺利氏、普莱克斯、优美科、台积电、中芯国际等国际巨头。公司是河南省首家生产半导体芯片核心材料的企业，定位「高端集成电路制造用材料+设备+零部件一站式服务平台」，业务由半导体核心材料、半导体设备、核心零部件三大板块构成，并探索「制造—设备—材料—零部件」融合的 FEMP 模式。① 半导体关键材料：核心为高纯溅射靶材（纯度要求 99.95% 以上），自研钌靶材可满足 3-5nm 先进制程，是国内唯一突破国外壁垒的同类产品，也是下一代 MRAM 存储器关键材料；镁靶材打破日本垄断实现量产；MRAM 系列靶材市占率全国第一，钴铁硼靶为国内独家量产，氧化镁靶等批量供货头部厂商；2021 年收购新加坡靶材公司 Allcent 100% 股权，产品进入台积电、格罗方德。② 半导体设备：2022 年通过收购上海讯颖电子切入，以二手设备改造为起点低成本适配国内产线，当前设备业务营收占比已超 50%；已具备炉管、CVD 等前道核心设备研发制造能力，炉管设备零部件国产化率达 95%，同时开展量测、光刻、涂胶显影、清洗等设备业务，并组建团队推进 A 路线光刻机研发。③ 核心零部件：自研光刻机直线电机实现纳米级磁悬浮移动，打破进口垄断并成为阿斯麦国内唯一配套供应商；光刻机光源、光纤、磁座、刻蚀机反应腔体、硅/石英/陶瓷零部件等数百种产品通过头部晶圆厂认证并批量进入供应链；掌握应用于高端制程反应腔体的喷涂技术（国内少数），自研高性能钡钪钨电极采用稀土钡、钪掺杂技术稳定产生 365nm 光刻波长光。营收：2019 年投产当年销售额突破 3500 万元，2022 年超 5 亿元，2024 年超 9 亿元，2025 年超 10 亿元（另一口径称超 15 亿元），连年高速增长。荣誉：2020 年国家级高新技术企业，2022 年国家级专精特新「小巨人」、中国创新创业大赛河南赛区冠军，2024 年国家级专精特新重点「小巨人」，2025 年「中国潜在独角兽」。客户覆盖中芯国际、台积电、格罗方德、希捷、北方华创、长鑫存储。基地布局郑州（200 亩集成电路产业园）、上海、北京、无锡、厦门、天津武清、香港。","valuation":30,"round":"C 轮","lastFunding":"2026-04","latestFunding":"C 轮进行中（2026 年 4 月媒体报道「即将完成」），估值 30 亿元；据亿欧数据，2026-04-30 完成一轮战略投资，投资方含中财融商。此前：2022 年 3 月完成 B 轮融资，投资方为建广资产、广大汇通；2020 年 7 月获建广资产 A 轮融资（成立不到两年即获投，亿欧记为天使轮），并被认定为国家级高新技术企业。","latestTech":"① 自研钌靶材满足 3-5nm 先进制程，国内唯一突破国外壁垒，为下一代 MRAM 存储器关键材料，MRAM 系列靶材市占率全国第一；② 自研光刻机直线电机实现纳米级磁悬浮移动，成为阿斯麦（ASML）国内唯一配套供应商；③ 掌握高端制程反应腔体喷涂技术，自研高性能钡钪钨电极可稳定产生 365nm 光刻波长光；④ 炉管设备零部件国产化率达 95%。","tech":[{"date":"2026-03","title":"香港元朗创新园半导体设备研发及生产基地项目启动","kind":"产能","desc":"投资 8 亿元，建全港首个半导体前端设备研发及生产基地，首期生产炉管、刻蚀、CVD 设备；最多可获港府「新型工业加速计划」2 亿元资助，预计 2027 年 6 月投产、产能达 10 亿元以上，面向内地及东南亚、中东市场。"},{"date":"2025-07","title":"光刻机用直线电机等关键零部件通过中芯国际、长鑫存储认证","kind":"认证","desc":"光刻机直线电机实现纳米级磁悬浮移动，打破进口垄断。"},{"date":"2025-03","title":"上海贺东基地交付六台晶圆制造高端设备","kind":"量产","desc":"正式发往行业头部企业，标志在高端半导体装备制造领域实现重大突破。"},{"date":"2021","title":"收购新加坡靶材公司 Allcent 100% 股权","kind":"并购","desc":"靶材产品进入台积电、格罗方德等优质客户供应链。"}],"funding":[{"date":"2026-04","round":"C轮/战略投资","amount":"未披露（估值30亿元）","inv":"中财融商等（据亿欧数据于 2026-04-30 完成战略投资；媒体 2026-04-27 报道称 C 轮「即将完成」）"},{"date":"2022-03","round":"B轮","amount":"未披露","inv":"建广资产、广大汇通等"},{"date":"2020-07","round":"A轮","amount":"未披露","inv":"建广资产（亿欧数据记为天使轮）"}],"investorsStructured":[{"name":"建广资产","role":"lead","round":"A轮/B轮","date":"2020-07","kind":"pe","note":"中关村融信金融信息化产业联盟旗下，半导体领域知名产业基金（曾主导恩智浦标准产品业务收购），连续参与 A、B 轮"},{"name":"广大汇通","role":"follow","round":"B轮","date":"2022-03","kind":"pe"},{"name":"中财融商","role":"follow","round":"C轮/战略投资","date":"2026-04","kind":"pe","note":"据亿欧数据；与媒体所述 C 轮时间吻合"}],"executives":[{"name":"王永超","title":"董事长","role":"board","bio":"郑州人，与团队在海外深耕十余年后归国创业，2018 年落户郑州航空港创立东微电子；主导公司「材料+设备+零部件」全链布局与香港基地等国际化战略。"},{"name":"赵泽良","title":"CEO","role":"management","bio":"河南女婿，海外半导体行业十余年从业经历，与董事长共同创立东微电子；主管公司经营，推动钌靶材、镁靶材与光刻机直线电机等关键产品突破。"},{"name":"郭金坡","title":"副总裁","role":"management","bio":"负责公司研发中心与产线运营，推进核心材料、设备及零部件业务规模化扩产阶段的洁净厂房环境控制与产线建设。"}],"note":"跨环节标的：虽挂载于「溅射靶材 / 高纯金属」，但三大板块中半导体设备营收占比已超 50%（以二手设备改造起步）；真正稀缺性在材料（钌靶材、MRAM 靶材全国第一且国内唯一）与零部件（ASML 国内唯一光刻机直线电机配套供应商）。营收口径存在差异（2025 年「超 10 亿元」与「超 15 亿元」两种说法）；C 轮 30 亿元估值为媒体口径，尚未经工商变更确认。注意：与池内「东微半导」（苏州东微半导体，688261.SH，功率器件）是完全不同的两家公司，勿混淆。"}'::jsonb,now()
)
